import { WORKBOOKS } from "./curriculum/workbooks";
import { MODULE_CONTENT } from "./curriculum/content";
import type { ModuleContent, WorkbookModule } from "./curriculum/types";

/*
 * The four academic programmes. Structure (codes, titles, slugs, pacing) lives
 * here; the module text comes verbatim from the programme workbooks
 * (src/lib/curriculum/workbooks.ts, generated by
 * scripts/import-curriculum-workbooks.mjs); the taught lessons, quizzes and
 * examination items are authored in src/lib/curriculum/content/.
 * `npm run curriculum:sync` writes all of it to the database.
 */

export type AcademicModule = Omit<WorkbookModule, "code" | "title" | "number"> & {
  code: string;
  title: string;
  /** The module's focus, from the level's curriculum map. */
  focus: string;
  /** The tangible output the workbook asks for, when the map names one. */
  output: string | null;
  content: ModuleContent;
};

export type AcademicCapstone = { title: string; introduction: string; prompts: string[] };

export type AcademicLevel = {
  slug: string;
  digitalLevelSlug: string;
  courseSlug: string;
  name: string;
  tagline: string;
  introduction: string;
  outcomes: string[];
  weeks: number;
  passMark: number;
  accent: string;
  icon: string;
  capstone: AcademicCapstone | null;
  modules: AcademicModule[];
};

export type AcademicProgramme = {
  slug: string;
  name: string;
  duration: string;
  structure: string;
  description: string;
  /** How sessions run, from the workbooks' facilitation guidance. */
  sessionFormat: string;
  levels: AcademicLevel[];
};

export type AcademicSessionDesign = {
  summary: string;
  focusQuestions: string[];
  format: string;
  durationMinutes: number;
};

type ModuleOutline = [code: string, title: string, focus: string, output?: string];
type LevelOutline = Omit<AcademicLevel, "introduction" | "outcomes" | "modules"> & { modules: ModuleOutline[] };
type ProgrammeOutline = Omit<AcademicProgramme, "levels"> & { levels: LevelOutline[] };

const comparable = (title: string) =>
  title.toLowerCase().replaceAll("&", "and").replaceAll(/[^a-z0-9]+/g, " ").trim();

function buildProgramme(outline: ProgrammeOutline): AcademicProgramme {
  const workbook = WORKBOOKS[outline.slug];
  if (!workbook) throw new Error(`No workbook imported for ${outline.slug}`);
  return {
    ...outline,
    levels: outline.levels.map((level, levelIndex) => {
      const source = workbook[String(levelIndex + 1)];
      if (!source || source.modules.length !== level.modules.length) {
        throw new Error(`${outline.slug} level ${levelIndex + 1}: workbook modules do not match the outline`);
      }
      const modules = level.modules.map(([code, title, focus, output], moduleIndex): AcademicModule => {
        const { number: _number, code: workbookCode, title: workbookTitle, ...text } = source.modules[moduleIndex];
        if (comparable(workbookTitle) !== comparable(title) || (workbookCode && workbookCode !== code)) {
          throw new Error(`${outline.slug} ${code}: outline "${title}" does not match workbook "${workbookCode ?? ""} ${workbookTitle}"`);
        }
        const content = MODULE_CONTENT[`${outline.slug}/${code}`];
        if (!content) throw new Error(`${outline.slug} ${code}: no authored lesson content`);
        return { ...text, code, title, focus, output: output ?? null, content };
      });
      return { ...level, introduction: source.overview, outcomes: modules.map((module) => module.focus), modules };
    }),
  };
}

