export function academicModuleKey(programmeSlug: string, levelSlug: string, moduleCode: string) {
  return `${programmeSlug}:${levelSlug}:${moduleCode.toLowerCase().replaceAll(/[^a-z0-9]+/g, "-")}`;
}

/**
 * The facilitated session for a module: the workbook's Module Introduction as
 * the summary and its five Module Assessment questions as the session's
 * inquiry questions. The final module of a level also prepares the capstone.
 */
export function academicSessionDesign(
  programme: Pick<AcademicProgramme, "sessionFormat">,
  module: AcademicModule,
  moduleIndex: number,
  moduleCount: number,
): AcademicSessionDesign {
  return {
    summary: module.introduction,
    focusQuestions: module.assessmentQuestions,
    format: moduleIndex === moduleCount - 1 ? `${programme.sessionFormat} + level capstone` : programme.sessionFormat,
    durationMinutes: 90,
  };
}
